# -*- coding: utf-8 -*-
"""Wave D step 7p research record: four files, one commit."""
def rd(p): return open(p, encoding='utf-8').read()
def wr(p, t): open(p, 'w', encoding='utf-8').write(t)
def rep(p, old, new):
    t = rd(p)
    n = t.count(old)
    assert n == 1, (p, old[:70], n)
    wr(p, t.replace(old, new))
def rep_all(p, old, new):
    t = rd(p)
    n = t.count(old)
    assert n == 2, (p, old[:70], n)
    wr(p, t.replace(old, new))

